import { cx } from "./cx";

export const glyphTone = {
  foreground: "text-foreground",
  secondary: "text-foreground-secondary",
  muted: "text-muted",
  tint: "text-tint",
  onSignal: "text-accent-foreground",
  danger: "text-danger",
  warning: "text-warning",
  success: "text-success",
  inherit: "",
} as const;

export type GlyphTone = keyof typeof glyphTone;
export type GlyphSize = 12 | 16 | 17 | 20 | 24 | 32;

/**
 * One kit glyph drawn from its markup (a module in ./glyphs, generated by scripts/vector-web.mjs), for client parts:
 * `import { check } from "../glyphs/check"` ships that one string, not the whole icon table that Icon (icon.tsx)
 * reads. 12 is the Choices check slot, 17 the Button glyph, 20 the default. Decorative unless `label` is given.
 * The size is inline so HeroUI's slot CSS (which sizes any svg inside a button) never changes it. The svg fills
 * with currentColor (the Ionicons stylesheet's `.ionicon` rule, which the generator strips), so filled glyphs
 * follow the tone; parts marked fill="none" stay outlines. `mirrored` flips a directional glyph under RTL. `name`
 * marks the svg (data-kit-icon) for the slot CSS. `data-*` attributes pass through, so a HeroUI slot that clones
 * the glyph (the Select indicator) can mark it open.
 */
export function Glyph({
  markup,
  name,
  size = 20,
  tone = "inherit",
  label,
  mirrored = false,
  className,
  ...data
}: {
  markup: string;
  name?: string;
  size?: GlyphSize;
  tone?: GlyphTone;
  label?: string;
  mirrored?: boolean;
  className?: string;
  [attribute: `data-${string}`]: string | boolean | undefined;
}) {
  return (
    <svg
      {...data}
      viewBox="0 0 512 512"
      width={size}
      height={size}
      fill="currentColor"
      style={{ width: size, height: size }}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
      data-kit-icon={name}
      className={cx("kit-icon shrink-0", glyphTone[tone], mirrored && "rtl:-scale-x-100", className)}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}
